SELECT COUNT(*)
FROM child c
WHERE c.child_id = #{childId}
  AND c.status = 'ACTIVE'
  AND (
    c.member_id = #{memberId}
        OR EXISTS (
        SELECT 1
        FROM child_parent cp
        WHERE cp.child_id = c.child_id
          AND cp.member_id = #{memberId}
    )
    )

SELECT
ar.allowance_request_id,
ar.child_id,
ar.requested_amount,
ar.status,
ar.requested_at
FROM allowance_request ar
WHERE ar.child_id = #{childId}


    AND ar.status = #{status}



    AND ar.allowance_request_id
    < #{cursorId}


ORDER BY ar.allowance_request_id DESC
LIMIT #{limit}

mapper.update:
UPDATE allowance_request
SET status = #{status},
    updated_at = #{updatedAt}
WHERE allowance_request_id = #{allowanceRequestId}
  AND status = 'PENDING'
